settings._cssCustom:
.crown-style-scope,
.crown-topbar,
.crown-header,
.crown-hero,
.crown-stats,
.crown-services,
.crown-why,
.crown-quote,
.crown-process,
.crown-proof,
.crown-final,
.crown-footer { --crown-red: var(--primary); --crown-ink: var(--secondary); --crown-gold: var(--accent); --crown-paper: var(--base-ultra-light); }
.crown-topbar, .crown-header, .crown-hero, .crown-stats, .crown-services, .crown-why, .crown-quote, .crown-process, .crown-proof, .crown-final, .crown-footer { padding-block: 0; }
.crown-container { width: min(var(--content-width), calc(100% - (2 * var(--gutter)))); margin-inline: auto; padding-inline: 0; }
.crown-topbar { min-height: 34px; background: var(--crown-ink); color: var(--white); font-size: var(--text-xs); }
.crown-topbar__inner { min-height: 34px; display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
.crown-topbar__group { width: auto; display: flex; flex-direction: row; align-items: center; gap: .7rem; }
.crown-topbar__icon { color: var(--white); font-size: .8rem; }
.crown-topbar__text { min-height: 0; margin: 0; padding: 0; border: 0; background: transparent; color: var(--white); font-size: var(--text-xs); }
.crown-header { background: var(--white); border-bottom: 1px solid color-mix(in srgb, var(--crown-ink) 12%, transparent); }
.crown-header__inner { min-height: 86px; display: grid; grid-template-columns: minmax(210px, .8fr) 2fr auto; align-items: center; gap: var(--space-m); }
.crown-header__logo { width: clamp(180px, 16vw, 245px); }
.crown-header__logo img { width: 100%; height: auto; }
.crown-nav { width: auto; display: flex; flex-direction: row; justify-content: flex-end; align-items: center; gap: clamp(1rem, 2.2vw, 2.4rem); }
.crown-nav__link { min-height: 0; padding: .5rem 0; border: 0; background: transparent; color: var(--crown-ink); font-size: var(--text-s); font-weight: 600; text-decoration: none; white-space: nowrap; }
.crown-btn { min-height: 48px; display: inline-flex; align-items: center; justify-content: center; padding: .85em 1.65em; border: 1px solid transparent; border-radius: 2px; font-family: var(--text-font-family); font-size: var(--text-s); font-weight: 800; line-height: 1; letter-spacing: 0; text-transform: uppercase; text-decoration: none; transition: background-color .2s ease, color .2s ease, transform .2s ease; }
.crown-btn:hover { transform: translateY(-1px); }
.crown-btn--primary { background: var(--crown-red); color: var(--white); }
.crown-btn--primary:hover { background: var(--primary-dark); color: var(--white); }
.crown-btn--outline { min-height: 42px; border-color: color-mix(in srgb, var(--crown-ink) 50%, transparent); background: transparent; color: var(--crown-ink); }
.crown-btn--outline:hover { background: var(--crown-ink); color: var(--white); }
.crown-eyebrow { margin: 0; color: var(--crown-red); font-size: var(--text-xs); font-weight: 800; line-height: 1.2; letter-spacing: 0; text-transform: uppercase; }
.crown-display { margin: 0; font-family: Anton, Impact, sans-serif; font-weight: 400; letter-spacing: 0; color: var(--crown-ink); text-wrap: balance; }
.crown-copy { margin: 0; max-width: 58ch; color: var(--text-dark-muted); line-height: 1.55; }
.crown-hero { position: relative; overflow: hidden; background: var(--crown-paper); }
.crown-hero__inner { width: 100%; min-height: clamp(540px, 47vw, 660px); display: grid; grid-template-columns: minmax(0, 39%) minmax(0, 61%); }
.crown-hero__content { position: relative; z-index: 2; justify-content: center; gap: var(--space-s); padding: clamp(3rem, 6vw, 7rem) clamp(2rem, 5vw, 5rem) clamp(3rem, 6vw, 6rem) max(var(--gutter), calc((100vw - var(--content-width)) / 2)); background: linear-gradient(90deg, var(--crown-paper) 0%, var(--crown-paper) 88%, color-mix(in srgb, var(--crown-paper) 90%, transparent) 100%); }
.crown-hero__title { max-width: 9.8ch; font-size: clamp(3.7rem, 6.3vw, 7rem); line-height: .92; }
.crown-hero__copy { max-width: 38ch; font-size: var(--text-m); }
.crown-hero__actions { width: auto; display: flex; flex-direction: row; align-items: center; flex-wrap: wrap; gap: var(--space-m); margin-top: var(--space-xs); }
.crown-phone { color: var(--crown-ink); font-size: var(--text-s); }
.crown-phone a { color: var(--crown-red); font-weight: 800; text-underline-offset: 3px; }
.crown-rating { width: auto; display: flex; flex-direction: row; align-items: center; gap: .75rem; margin-top: var(--space-xs); }
.crown-rating__g { color: #4285f4; font-size: 1.5rem; font-weight: 800; }
.crown-rating__stars { color: var(--crown-gold); letter-spacing: 0; }
.crown-rating__label { color: var(--crown-ink); font-size: var(--text-s); }
.crown-hero__media { position: relative; min-height: 100%; overflow: hidden; }
.crown-hero__image { position: absolute; inset: 0; width: 100%; height: 100%; }
.crown-hero__image img { width: 100%; height: 100%; object-fit: cover; object-position: center; }
.crown-hero__badge { position: absolute; left: 0; bottom: 0; z-index: 2; width: min(250px, 42%); min-height: 135px; display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 1rem; padding: 1.4rem 1.6rem; background: var(--white); box-shadow: var(--box-shadow-2); }
.crown-hero__badge-icon { color: var(--crown-gold); font-size: 2.2rem; }
.crown-hero__badge-value { color: var(--crown-ink); font-family: Anton, Impact, sans-serif; font-size: clamp(2rem, 3vw, 3.5rem); line-height: 1; }
.crown-hero__badge-label { color: var(--crown-ink); font-size: var(--text-s); line-height: 1.25; }
.crown-stats { background: var(--crown-ink); color: var(--white); }
.crown-stats__inner { min-height: 150px; display: grid; grid-template-columns: repeat(3, 1fr); align-items: center; }
.crown-stat { position: relative; align-items: center; justify-content: center; gap: .35rem; text-align: center; }
.crown-stat + .crown-stat { border-left: 1px solid color-mix(in srgb, var(--white) 32%, transparent); }
.crown-stat__icon { color: var(--crown-gold); font-size: 2.25rem; }
.crown-stat__value { color: var(--white); font-family: Anton, Impact, sans-serif; font-size: clamp(2.4rem, 4vw, 4rem); line-height: 1; }
.crown-stat__label { color: var(--white); font-size: var(--text-s); font-weight: 700; letter-spacing: 0; text-transform: uppercase; }
.crown-stat__stars { color: var(--crown-gold); }
.crown-services { background: var(--crown-paper); }
.crown-services__inner { min-height: 285px; display: grid; grid-template-columns: minmax(260px, 1.2fr) 2.8fr; align-items: center; gap: clamp(2rem, 5vw, 5rem); padding-block: var(--section-space-s); }
.crown-services__intro { gap: .75rem; }
.crown-services__title { max-width: 11ch; font-size: clamp(2.7rem, 4vw, 4.7rem); line-height: .98; }
.crown-services__grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; }
.crown-service { min-width: 0; min-height: 190px; justify-content: center; gap: .65rem; padding: 1rem clamp(1rem, 2vw, 2rem); border-left: 1px solid color-mix(in srgb, var(--crown-ink) 25%, transparent); }
.crown-service__icon { width: 48px; height: 48px; object-fit: contain; }
.crown-service__name { font-size: var(--text-m); line-height: 1.15; }
.crown-service__copy { margin: 0; color: var(--text-dark-muted); font-size: var(--text-s); line-height: 1.5; }
.crown-why { background: var(--white); }
.crown-why__inner { width: 100%; display: grid; grid-template-columns: 52% 48%; min-height: 450px; }
.crown-why__media { min-height: 450px; }
.crown-why__image, .crown-why__image img { width: 100%; height: 100%; }
.crown-why__image img { object-fit: cover; object-position: center; }
.crown-why__content { justify-content: center; gap: .75rem; padding: clamp(2.5rem, 5vw, 6rem); }
.crown-why__title { max-width: 12ch; font-size: clamp(3rem, 4.7vw, 5.4rem); line-height: .95; }
.crown-checklist { gap: .55rem; margin-top: .5rem; }
.crown-check { width: auto; display: flex; flex-direction: row; align-items: center; gap: .75rem; }
.crown-check__icon { color: var(--crown-red); font-size: .95rem; }
.crown-check__text { margin: 0; color: var(--crown-ink); font-size: var(--text-s); }
.crown-why__link { width: fit-content; margin-top: .5rem; color: var(--crown-red); font-size: var(--text-s); font-weight: 800; text-transform: uppercase; text-decoration: none; }
.crown-quote { background: var(--crown-ink); color: var(--white); }
.crown-quote__inner { display: grid; grid-template-columns: .9fr 1.35fr; align-items: center; gap: clamp(2.5rem, 6vw, 7rem); padding-block: var(--section-space-s); }
.crown-quote__content { gap: .85rem; }
.crown-quote__title { max-width: 13ch; color: var(--white); font-size: clamp(3rem, 4.6vw, 5.2rem); line-height: .96; }
.crown-quote__copy { color: color-mix(in srgb, var(--white) 82%, transparent); }
.crown-quote__features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.2rem; margin-top: 1rem; }
.crown-quote-feature { display: grid; grid-template-columns: auto 1fr; align-items: center; gap: .7rem; }
.crown-quote-feature__icon { color: var(--crown-gold); font-size: 1.6rem; }
.crown-quote-feature__text { margin: 0; color: var(--white); font-size: var(--text-xs); }
.crown-quote__form { padding: clamp(1.2rem, 2.2vw, 2.2rem); border-radius: 4px; background: var(--white); color: var(--crown-ink); box-shadow: var(--box-shadow-2); }
.crown-quote__form .wsf-form { margin: 0; }
.crown-quote__form input, .crown-quote__form select, .crown-quote__form textarea { min-height: 44px; border-radius: 2px !important; }
.crown-quote__form button[type='submit'] { width: 100%; min-height: 50px; border-radius: 2px !important; background: var(--crown-red) !important; color: var(--white) !important; font-weight: 800; text-transform: uppercase; }
.crown-process { background: var(--crown-paper); }
.crown-process__inner { align-items: center; gap: var(--space-m); padding-block: var(--section-space-xs); }
.crown-process__title { font-size: clamp(2.8rem, 4vw, 4.7rem); text-align: center; }
.crown-process__steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(2rem, 7vw, 7rem); }
.crown-step { position: relative; display: grid; grid-template-columns: auto 1fr; align-items: start; gap: 1.1rem; }
.crown-step:not(:last-child)::after { content: '→'; position: absolute; right: clamp(-4.5rem, -4vw, -2rem); top: .4rem; color: var(--crown-gold); font-size: 2.6rem; font-weight: 300; }
.crown-step__number { color: var(--crown-red); font-family: Anton, Impact, sans-serif; font-size: 3.25rem; line-height: 1; }
.crown-step__body { gap: .3rem; }
.crown-step__heading { font-size: var(--text-m); }
.crown-step__copy { margin: 0; color: var(--text-dark-muted); font-size: var(--text-xs); line-height: 1.45; }
.crown-proof { background: var(--white); }
.crown-proof__inner { width: 100%; display: grid; grid-template-columns: 47% 53%; min-height: 235px; }
.crown-testimonial { justify-content: center; gap: .75rem; padding: clamp(2rem, 4vw, 4.5rem) max(var(--gutter), calc((100vw - var(--content-width)) / 2)); background: var(--crown-red); }
.crown-testimonial__mark { color: var(--white); font-family: Georgia, serif; font-size: 3.6rem; line-height: .5; }
.crown-testimonial__quote { max-width: 17ch; color: var(--white); font-size: clamp(2.3rem, 3.7vw, 4.2rem); line-height: 1; }
.crown-testimonial__meta { color: var(--white); font-size: var(--text-s); }
.crown-testimonial__stars { color: var(--white); letter-spacing: 0; }
.crown-map { position: relative; min-height: 235px; overflow: hidden; background: var(--crown-paper); }
.crown-map__image { position: absolute; inset: 0; width: 100%; height: 100%; opacity: .55; }
.crown-map__image img { width: 100%; height: 100%; object-fit: cover; }
.crown-marker { position: absolute; z-index: 2; width: auto; transform: translate(-50%, -50%); display: flex; flex-direction: row; align-items: center; gap: .4rem; }
.crown-marker__icon { color: var(--crown-red); font-size: 1rem; }
.crown-marker__label { color: var(--crown-ink); font-size: var(--text-xs); font-weight: 700; white-space: nowrap; }
.crown-final { position: relative; overflow: hidden; background: var(--crown-ink); }
.crown-final__inner { width: 100%; min-height: 265px; display: grid; grid-template-columns: 43% 57%; }
.crown-final__content { position: relative; z-index: 2; justify-content: center; gap: 1rem; padding: 2rem max(var(--gutter), calc((100vw - var(--content-width)) / 2)); background: linear-gradient(90deg, var(--crown-ink) 0%, var(--crown-ink) 84%, transparent 100%); }
.crown-final__title { max-width: 11ch; color: var(--white); font-size: clamp(2.9rem, 4.2vw, 4.9rem); line-height: .98; }
.crown-final__actions { width: auto; display: flex; flex-direction: row; align-items: center; gap: 1.5rem; }
.crown-final__phone { min-height: 0; padding: 0; border: 0; background: transparent; color: var(--white); font-weight: 700; }
.crown-final__media, .crown-final__image, .crown-final__image img { width: 100%; height: 100%; }
.crown-final__image img { object-fit: cover; object-position: center; }
.crown-footer { background: var(--crown-ink); color: var(--white); border-top: 1px solid color-mix(in srgb, var(--white) 15%, transparent); }
.crown-footer__inner { display: grid; grid-template-columns: 1.3fr repeat(3, 1fr) auto; gap: clamp(2rem, 5vw, 5rem); padding-block: var(--section-space-s); }
.crown-footer__brand { gap: .65rem; }
.crown-footer__logo { width: 220px; }
.crown-footer__logo img { width: 100%; height: auto; }
.crown-footer__text, .crown-footer__link { margin: 0; color: color-mix(in srgb, var(--white) 78%, transparent); font-size: var(--text-xs); line-height: 1.6; text-decoration: none; }
.crown-footer__link { min-height: 0; padding: 0; border: 0; background: transparent; }
.crown-footer__heading { color: var(--white); font-size: var(--text-s); text-transform: uppercase; }
.crown-footer__col { gap: .5rem; }
.crown-footer__bottom { width: min(var(--content-width), calc(100% - (2 * var(--gutter)))); margin-inline: auto; display: flex; flex-direction: row; justify-content: space-between; padding-block: 1.2rem; border-top: 1px solid color-mix(in srgb, var(--white) 12%, transparent); }
@media (max-width: 991px) {
  .crown-header__inner { grid-template-columns: 1fr auto; min-height: 72px; }
  .crown-nav { display: none; }
  .crown-hero__inner, .crown-why__inner, .crown-quote__inner, .crown-proof__inner, .crown-final__inner { grid-template-columns: 1fr; }
  .crown-hero__content { padding: var(--section-space-s) var(--gutter); }
  .crown-hero__media { min-height: 520px; }
  .crown-services__inner { grid-template-columns: 1fr; }
  .crown-services__grid { grid-template-columns: repeat(2, 1fr); }
  .crown-service:nth-child(odd) { border-left: 0; }
  .crown-why__media { min-height: 480px; }
  .crown-quote__inner { padding-block: var(--section-space-m); }
  .crown-map { min-height: 320px; }
  .crown-final__media { min-height: 360px; }
  .crown-footer__inner { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 767px) {
  .crown-topbar__inner { padding-block: .35rem; }
  .crown-topbar__group:first-child { display: none; }
  .crown-header__cta { min-height: 40px; padding-inline: .9rem; font-size: .75rem; }
  .crown-hero__title { font-size: clamp(3.2rem, 16vw, 5.2rem); }
  .crown-hero__media { min-height: 390px; }
  .crown-hero__badge { width: min(240px, 72%); min-height: 110px; }
  .crown-stats__inner { grid-template-columns: 1fr; padding-block: 1rem; }
  .crown-stat { min-height: 110px; }
  .crown-stat + .crown-stat { border-left: 0; border-top: 1px solid color-mix(in srgb, var(--white) 25%, transparent); }
  .crown-services__grid { grid-template-columns: 1fr; }
  .crown-service, .crown-service:nth-child(odd) { min-height: 155px; border-left: 0; border-top: 1px solid color-mix(in srgb, var(--crown-ink) 18%, transparent); }
  .crown-quote__features { grid-template-columns: 1fr; }
  .crown-process__steps { grid-template-columns: 1fr; gap: 2rem; }
  .crown-step:not(:last-child)::after { display: none; }
  .crown-final__actions { align-items: flex-start; flex-direction: column; }
  .crown-footer__inner { grid-template-columns: 1fr; }
  .crown-footer__bottom { flex-direction: column; gap: .5rem; }
}
